import json
import sys
import time
import random

from text_index_engine import query
from text_index_engine.analysis import tokenize
from text_index_engine.snapshot import Snapshot, build_from_lines
from text_index_engine.query import (
    _lex, T_EOF, T_AND, T_OR, T_NOT, T_LPAREN, T_RPAREN,
)

docs = [
    {"id": "a", "text": "alpha beta gamma delta"},
    {"id": "b", "text": "alpha gamma"},
    {"id": "c", "text": ""},
    {"id": "d", "text": "beta café quick"},
    {"id": "中", "text": "快速 快狐"},
]
snap = Snapshot.load(build_from_lines(
    [json.dumps(d, ensure_ascii=False) + "\n" for d in docs]))
sys.setrecursionlimit(60000)  # only the independent reference recurses

LEAVES = ["alpha", "beta", "gamma", "delta", "café", "quick", "zzz",
          "al*", "快*", '"alpha beta"', '"gamma delta"', '"zzz q"']


class Ref:
    """Independent recursive-descent parser + set evaluator."""

    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self):
        return self.t[self.i]

    def adv(self):
        x = self.t[self.i]
        self.i += 1
        return x

    def parse(self):
        n = self.orx()
        assert self.peek().kind == T_EOF
        return n

    def orx(self):
        l = self.andx()
        while self.peek().kind == T_OR:
            self.adv()
            l = ("or", l, self.andx())
        return l

    def andx(self):
        l = self.notx()
        while self.peek().kind == T_AND:
            self.adv()
            l = ("and", l, self.notx())
        return l

    def notx(self):
        if self.peek().kind == T_NOT:
            self.adv()
            return ("not", self.notx())
        x = self.peek()
        if x.kind == T_LPAREN:
            self.adv()
            n = self.orx()
            assert self.adv().kind == T_RPAREN
            return n
        self.adv()
        return (x.kind.lower(), x.value)


DOCWORDS = {d["id"]: tokenize(d["text"]) for d in docs}
U = frozenset(DOCWORDS)
P = {}
for d, toks in DOCWORDS.items():
    for w in toks:
        P.setdefault(w, set()).add(d)


def ref_ev(n):
    k = n[0]
    if k == "term":
        return set(P.get(n[1], ()))
    if k == "prefix":
        return {d for t, ps in P.items() if t.startswith(n[1]) for d in ps}
    if k == "phrase":
        out = set()
        for d, toks in DOCWORDS.items():
            for i in range(len(toks) - len(n[1]) + 1):
                if toks[i:i + len(n[1])] == n[1]:
                    out.add(d)
                    break
        return out
    if k == "not":
        return set(U) - ref_ev(n[1])
    if k == "and":
        return ref_ev(n[1]) & ref_ev(n[2])
    return ref_ev(n[1]) | ref_ev(n[2])


rng = random.Random(1234)


def gen(depth):
    r = rng.random()
    if depth <= 0 or r < 0.35:
        return rng.choice(LEAVES)
    if r < 0.5:
        return "NOT " + gen(depth - 1)
    if r < 0.7:
        return "(" + gen(depth - 1) + ")"
    op = " AND " if r < 0.85 else " OR "
    parts = [gen(depth - 1) for _ in range(rng.randint(2, 4))]
    return op.join(parts)


trials = 400
t0 = time.time()
for _ in range(trials):
    q = gen(rng.randint(200, 4000))
    prod = sorted(query.evaluate(query.parse(q), snap))
    ref = sorted(ref_ev(Ref(_lex(q)).parse()))
    assert prod == ref, q[:200]
print(f"{trials} random deep expressions match independent reference "
      f"({time.time() - t0:.1f}s)")

for name, q in [("not", "NOT " * 10000 + "alpha"),
                ("paren", "(" * 10000 + "alpha" + ")" * 10000),
                ("and", "alpha" + " AND alpha" * 9999),
                ("or", "zzz" + " OR alpha" * 9999)]:
    t0 = time.time()
    r = sorted(query.evaluate(query.parse(q), snap))
    print(f"{name:5s} {time.time() - t0:6.2f}s -> {r}")

